export const BODY: string = "\n<p>ضغط عشرات الصور دفعة واحدة أسهل مما تتوقع. ترفع المجلد كاملًا، وتختار إعدادًا جاهزًا، وتشغّل الدفعة، وتنزّل كل شيء كملف ZIP واحد.</p>\n<p>هذه الطريقة توفر ساعات للمدونين وأصحاب المتاجر. بدل ضغط كل صورة على حدة، تنتهي الدفعة كاملة في دقائق.</p>\n<p>يمر هذا الدليل بكل خطوة، من فتح الأداة إلى رفع النتائج، مع سير عمل للمدونات والمتاجر والألبومات.</p>\n<h2 id=\"what-you-need\">ما الذي تحتاجه قبل البدء؟</h2>\n<p>تحتاج إلى مجلد الصور الأصلية، ومعرفة الهدف الذي تريده لكل صورة، ومتصفح حديث. هذه الثلاثة تكفي للبدء.</p>\n<p>تأكد من أن الصور هي الملفات الأصلية لا نسخ مضغوطة. البدء من الأصل يعطي أفضل جودة في كل صورة بالدفعة.</p>\n<h2 id=\"step-1-open\">الخطوة 1: افتح ضاغط الجملة</h2>\n<p>افتح <a href=\"/ar/daght-jumli-lis-suwar/\">ضاغط الصور بالجملة</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-add-files\">الخطوة 2: أضف صورك</h2>\n<p>أسقط كل صورك في منطقة الرفع أو اختر المجلد كاملًا. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت لكل ملف.</p>\n<p>ستظهر كل صورة في قائمة مع حجمها الأصلي. تحقق من أن كل الصور المطلوبة موجودة قبل المتابعة.</p>\n<h2 id=\"step-3-preset\">الخطوة 3: اختر إعدادًا جاهزًا</h2>\n<p>اختر إعدادًا جاهزًا حسب هدفك: خفيف للجودة العالية، ومتوازن للاستخدام العام، وصغير لأصغر حجم ممكن.</p>\n<p>لصور المدونة، الإعداد المتوازن هو الخيار الآمن. يعطي جودة جيدة وحجمًا صغيرًا دون تعديلات إضافية.</p>\n<h2 id=\"step-4-run\">الخطوة 4: نفّذ الدفعة</h2>\n<p>اضغط زر التشغيل واترك الدفعة تعمل. تعالج الأداة كل صورة على حدة، وتظهر النتائج تدريجيًا مع شريط تقدم.</p>\n<p>الدفعة المتوسطة من 20 صورة تستغرق دقائق معدودة. يمكنك متابعة التقدم وترك الأداة تعمل في الخلفية.</p>\n<h2 id=\"step-5-preview\">الخطوة 5: راجع النتائج الفردية</h2>\n<p>بعد انتهاء الدفعة، راجع النتائج الفردية. افتح عينة من الصور وتأكد من جودتها، ولاحظ أي صورة ظهر عليها تحذير.</p>\n<p>إذا بدت العينة جيدة، فالدفعة ناجحة. وإذا فشلت صورة واحدة، فأعد ضغطها وحدها بإعدادات مختلفة.</p>\n<h2 id=\"step-6-download-zip\">الخطوة 6: نزّل ملف ZIP</h2>\n<p>نزّل كل النتائج كملف ZIP واحد. الملف يحافظ على أسماء الصور الأصلية، فيسهل العثور على كل صورة بعد فك الضغط.</p>\n<p>فك ضغط الملف في مجلد جديد منفصل عن الأصول. التنظيم الجيد يمنع الخلط بين النسخ الأصلية والمضغوطة.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل في دفعة؟</h2>\n<p>إذا فشلت صورة في الدفعة، فافحص سبب الفشل أولًا. الصورة المزدحمة بالتفاصيل أو بصيغة PNG قد تحتاج إعدادات مختلفة.</p>\n<p>أعد ضغط الصورة الفاشلة وحدها بصيغة JPG أو بقص أذكى. لا تعيد الدفعة كاملة من أجل صورة واحدة.</p>\n<h2 id=\"blog-workflow\">سير العمل: مجموعة صور مدونة مصغرة</h2>\n<p>لمجموعة صور مدونة مصغرة، اختر الإعداد المتوازن وهدف 100 كيلوبايت. الصور المصغرة تظهر صغيرة، فلا حاجة إلى ملفات كبيرة.</p>\n<p>سمِّ كل صورة باسم يصف موضوع المقالة. ذلك يساعد محركات البحث على فهم الصور وربطها بالمحتوى.</p>\n<h2 id=\"shop-workflow\">سير العمل: كتالوج منتج</h2>\n<p>لكتالوج منتج، استخدم إعدادًا موحدًا لكل الصور: نفس الهدف ونفس الصيغة. التوحيد يجعل المتجر يبدو متناسقًا واحترافيًا.</p>\n<p>قصّ صور المنتجات على المنتج نفسه قبل الضغط. القص المحكم يمنح المنتج حصة أكبر من الميزانية فيبدو أوضح.</p>\n<h2 id=\"album-workflow\">سير العمل: ألبوم صور مشترك</h2>\n<p>لألبوم صور مشترك، اضغط الدفعة كاملة إلى حجم مناسب للمشاركة، مثل 200 كيلوبايت لكل صورة. الألبوم سيحمل بسرعة على أي جهاز.</p>\n<p>شارك ملف ZIP واحدًا بدل إرسال الصور واحدة تلو الأخرى. الملف الواحد أسهل في التنزيل والتنظيم.</p>\n<h2 id=\"folder-selection\">كيف تختار مجلدًا كاملًا دفعة واحدة؟</h2>\n<p>لاختيار مجلد كامل دفعة واحدة، استخدم زر اختيار المجلد في نافذة الرفع. يرفع المتصفح كل الصور في المجلد معًا.</p>\n<p>إذا كان المجلد يحمل ملفات غير صور، فستتجاهلها الأداة تلقائيًا. لا حاجة إلى فرز المجلد قبل الرفع.</p>\n<h2 id=\"progress-bar\">كيف تقرأ شريط التقدم؟</h2>\n<p>شريط التقدم يعرض عدد الصور المكتملة والمتبقية ونسبة الإنجاز. عندما يصل إلى 100 بالمئة، تكون الدفعة جاهزة للتنزيل.</p>\n<p>إذا توقف الشريط طويلًا على صورة واحدة، فقد تكون تلك الصورة كبيرة جدًا أو بصيغة غير معتادة. انتظر قليلًا قبل إلغاء الدفعة.</p>\n<h2 id=\"per-file-results\">كيف تفهم النتائج لكل ملف؟</h2>\n<p>النتائج لكل ملف تعرض الحجم الأصلي والحجم النهائي ونسبة التوفير. الصورة التي وفّرت 70 بالمئة أو أكثر ناجحة بامتياز.</p>\n<p>لاحظ الصور التي ظهر عليها تحذير. هذه الصور تحتاج إعادة ضغط فردية بإعدادات مختلفة.</p>\n<h2 id=\"retrying-failed\">كيف تعيد محاولة الملفات الفاشلة أو السيئة؟</h2>\n<p>لإعادة محاولة ملف فاشل، أعد ضغطه وحده من الملف الأصلي. جرّب صيغة JPG أولًا، ثم قصًا أذكى، ثم أبعادًا أصغر.</p>\n<p>إذا فشل الملف مجددًا، فقد يكون تالفًا أو بصيغة غير مدعومة. تحقق من فتحه في عارض صور قبل إعادة المحاولة.</p>\n<h2 id=\"uploading-after-batch\">كيف ترفع نتائج الدفعة؟</h2>\n<p>بعد تنزيل ملف ZIP، فك ضغطه في مجلد جديد وراجع النتائج. ثم ارفع الصور إلى موقعك أو مدونتك دفعة واحدة.</p>\n<p>احتفظ بنسخة من ملف ZIP كنسخة احتياطية. إذا حدث خطأ أثناء الرفع، فلديك النتائج جاهزة دون إعادة الضغط.</p>\n<h2 id=\"time-estimates\">كم تستغرق الدفعة؟</h2>\n<p>دفعة من 20 صورة تستغرق عادة دقائق معدودة. الوقت يعتمد على حجم الصور الأصلية وسرعة جهازك.</p>\n<p>الصور الكبيرة من الكاميرات الاحترافية تأخذ وقتًا أطول. للدفعات الكبيرة جدًا، قسّمها إلى مجموعات من 20 إلى 30 صورة.</p>\n<h2 id=\"sharing-zip\">كيف تشارك ملف ZIP مع الآخرين؟</h2>\n<p>لمشاركة ملف ZIP مع الآخرين، أرسله عبر البريد أو خدمة مشاركة ملفات. الملف الواحد أسهل من إرسال عشرات الصور منفصلة.</p>\n<p>إذا كان الملف كبيرًا جدًا للبريد، فارفعه إلى خدمة سحابية وشارك الرابط. المستلم ينزّل الملف ويفك ضغطه بنفسه.</p>\n<h2 id=\"cleanup-after\">كيف تنظّف بعد الدفعة؟</h2>\n<p>بعد الدفعة، احذف الملفات المؤقتة ونظّم مجلداتك: الأصول في مجلد، والنتائج في مجلد آخر. التنظيف يمنع الخلط في الدفعات القادمة.</p>\n<p>احتفظ بنسخة احتياطية من الأصول قبل حذف أي شيء. الأصل لا يمكن استعادته إذا حُذف بعد الضغط.</p>\n<h2 id=\"final-check\">مراجعة أخيرة قبل الرفع</h2>\n<p>قبل الرفع، راجع عينة من الدفعة: افتح 5 صور عشوائية وتأكد من جودتها وأبعادها وأسمائها.</p>\n<p>إذا بدت العينة جيدة، فالدفعة جاهزة. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-suwar-al-jumli/\">الدليل الكامل لضاغط الصور بالجملة</a> و<a href=\"/ar/blog/afdal-mumarasat-li-daght-as-suwar-al-jumli/\">أفضل ممارسات ضغط الصور بالجملة</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a> لأحجام دقيقة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضغط مجلدًا كاملًا من الصور دفعة واحدة؟","answer":"اختر المجلد كاملًا في نافذة الرفع، أو اسحب كل الملفات دفعة واحدة إلى منطقة الرفع. الأداة تقبل عشرات الملفات معًا وتعالجها بإعدادات واحدة."},{"question":"ما الإعداد الجاهز الذي أستخدمه لصور المدونة المصغرة؟","answer":"الإعداد المتوازن هو الخيار الآمن لصور المدونة المصغرة. يعطي جودة جيدة وحجمًا صغيرًا، ويناسب معظم الصور دون تعديلات إضافية."},{"question":"هل يمكنني ضغط صور على هاتفي بالجملة؟","answer":"نعم، افتح الأداة في متصفح هاتفك واختر عدة صور من معرضك. لكن الدفعات الكبيرة قد تستهلك ذاكرة الهاتف، فقسّمها إلى مجموعات صغيرة."},{"question":"ماذا يحدث إذا نفدت ذاكرة هاتفي أثناء الدفعة؟","answer":"قد تتوقف الدفعة أو تفشل بعض الصور. أغلق التطبيقات الأخرى قبل البدء، وقسّم الدفعات الكبيرة إلى مجموعات من 10 إلى 15 صورة."},{"question":"هل أحتاج إلى تغيير حجم الصور قبل الضغط بالجملة؟","answer":"ليس ضروريًا. الضغط يتعامل مع الأبعاد تلقائيًا، ولا يقلّصها إلا عند الحاجة. لكن إذا أردت أبعادًا موحدة، فغيّر الحجم أولًا ثم اضغط."},{"question":"كيف أعرف أن الدفعة وفّرت مساحة فعلًا؟","answer":"يعرض ملخص الدفعة الحجم الأصلي الإجمالي والحجم النهائي ونسبة التوفير. إذا كان التوفير 70 بالمئة أو أكثر، فالدفعة ناجحة."}];
